Item.method_code:
/*
    共通
    任意のアイテムからドキュメントへのリレーション名を取得する
*/

using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    Innovator inn = this.getInnovator();
    
    // 引数取得 
    string typename = this.getProperty("typename");
    
    Item itemtypenam = inn.newItem("ItemType", "get");
    itemtypenam.setAttribute( "select", "id" );    
	itemtypenam.setProperty("name", typename);
    itemtypenam = itemtypenam.apply();
    string parid = itemtypenam.getProperty("id", "");

    itemtypenam = inn.newItem("ItemType", "get");
    itemtypenam.setAttribute( "select", "id" );    
	itemtypenam.setProperty("name", "Document");
    itemtypenam = itemtypenam.apply();
    string docid = itemtypenam.getProperty("id", "");

    Item relname = inn.newItem("relationshiptype", "get"); 
    relname.setAttribute( "select", "name" );    
	relname.setProperty("source_id", parid);  
	relname.setProperty("related_id", docid); 
    relname = relname.apply();
    
    // 結局呼び出し元でエラーチェックと個数チェックをするので、そのまま返す
    return relname;
}
